    <div class="plot-app" data-testid="plot-root">
      <div class="workspace-header">
        <div>
          <p class="workspace-kicker">05 · Data Visualization</p>
          <h1 class="workspace-title">Plot Chart Studio</h1>
          <p class="workspace-subtitle">Turn a CSV into a bar, line or scatter chart. Missing and non-numeric cells are reported row by row, never silently guessed. Downloads are real SVG and PNG files built in your browser. Nothing is uploaded.</p>
        </div>
        <div class="control-row">
          <button type="button" class="btn" data-testid="plot-load-sample">Reset Sample Data</button>
        </div>
      </div>

      <div data-testid="plot-error" role="alert" class="alert-banner" hidden></div>

      <div class="panel-grid">
        <div class="col-4 plot-side">
          <section class="panel" aria-labelledby="plot-data-heading">
            <h2 class="panel-title" id="plot-data-heading">Data</h2>
            <p class="plot-dataset-info" data-testid="plot-dataset-info"></p>
            <div class="control-group">
              <label for="plot-file-input">Load local .CSV file (max 5 MB)</label>
              <input type="file" id="plot-file-input" data-testid="plot-file-input" accept=".csv,text/csv,text/plain" />
            </div>
            <div class="control-group">
              <label for="plot-textarea">Or paste CSV text</label>
              <textarea id="plot-textarea" data-testid="plot-textarea" class="mono-input" rows="8" spellcheck="false"></textarea>
            </div>
            <button type="button" class="btn btn-primary" data-testid="plot-parse-btn">Plot Pasted CSV</button>
          </section>

          <section class="panel" aria-labelledby="plot-settings-heading">
            <h2 class="panel-title" id="plot-settings-heading">Chart</h2>
            <fieldset class="plot-fieldset">
              <legend class="field-label">Chart type</legend>
              <div class="plot-type-group">
                <label class="plot-type-option"><input type="radio" name="plot-type" value="bar" data-testid="plot-type-bar" checked /> Bar</label>
                <label class="plot-type-option"><input type="radio" name="plot-type" value="line" data-testid="plot-type-line" /> Line</label>
                <label class="plot-type-option"><input type="radio" name="plot-type" value="scatter" data-testid="plot-type-scatter" /> Scatter</label>
              </div>
            </fieldset>
            <div class="plot-two-col">
              <div class="control-group">
                <label for="plot-x-col">X axis column</label>
                <select id="plot-x-col" data-testid="plot-x-col"></select>
              </div>
              <div class="control-group">
                <label for="plot-y-col">Y axis column</label>
                <select id="plot-y-col" data-testid="plot-y-col"></select>
              </div>
            </div>
            <div class="control-group">
              <label for="plot-missing-mode">Missing or non-numeric values</label>
              <select id="plot-missing-mode" data-testid="plot-missing-mode" aria-describedby="plot-missing-help">
                <option value="skip">Skip the row</option>
                <option value="gap">Break the line (line chart)</option>
              </select>
              <span class="plot-help" id="plot-missing-help">Excluded rows are always listed under the chart.</span>
            </div>
            <div class="control-group">
              <label for="plot-title-input">Chart title</label>
              <input type="text" id="plot-title-input" data-testid="plot-title-input" maxlength="120" placeholder="Optional" />
            </div>
            <div class="plot-two-col">
              <div class="control-group">
                <label for="plot-xlabel-input">X axis label</label>
                <input type="text" id="plot-xlabel-input" data-testid="plot-xlabel-input" maxlength="120" />
              </div>
              <div class="control-group">
                <label for="plot-ylabel-input">Y axis label</label>
                <input type="text" id="plot-ylabel-input" data-testid="plot-ylabel-input" maxlength="120" />
              </div>
            </div>
            <div class="plot-two-col">
              <div class="control-group">
                <label for="plot-width-input">Width (px)</label>
                <input type="number" id="plot-width-input" data-testid="plot-width-input" inputmode="numeric"
                  min="${K.minWidth}" max="${K.maxWidth}" step="10" value="${K.defaultWidth}" />
              </div>
              <div class="control-group">
                <label for="plot-height-input">Height (px)</label>
                <input type="number" id="plot-height-input" data-testid="plot-height-input" inputmode="numeric"
                  min="${K.minHeight}" max="${K.maxHeight}" step="10" value="${K.defaultHeight}" />
              </div>
            </div>
          </section>
        </div>

        <section class="panel col-8 plot-output" aria-labelledby="plot-preview-heading">
          <h2 class="panel-title" id="plot-preview-heading">Preview &amp; Export</h2>
          <div class="plot-preview" data-testid="plot-preview"></div>
          <p class="plot-exclusions" data-testid="plot-exclusions" aria-live="polite"></p>
          <div class="plot-export-row">
            <div class="control-group plot-scale-group">
              <label for="plot-png-scale">PNG resolution</label>
              <select id="plot-png-scale" data-testid="plot-png-scale" aria-describedby="plot-png-size">
                <option value="1">1× (chart size)</option>
                <option value="2" selected>2× (sharp)</option>
                <option value="3">3×</option>
                <option value="4">4× (print)</option>
              </select>
            </div>
            <div class="plot-export-buttons">
              <button type="button" class="btn btn-primary" data-testid="plot-download-svg">Download .SVG</button>
              <button type="button" class="btn btn-primary" data-testid="plot-download-png">Download .PNG</button>
            </div>
          </div>
          <p class="plot-help" id="plot-png-size" data-testid="plot-png-size"></p>
          <p class="plot-status" data-testid="plot-status" role="status"></p>
          <details class="plot-table-details">
            <summary>Plotted data table</summary>
            <div class="table-scroll">
              <table class="data-table" data-testid="plot-data-table">
                <caption class="plot-caption"></caption>
                <thead><tr><th scope="col">CSV row</th><th scope="col" data-col="x">X</th><th scope="col" data-col="y">Y</th></tr></thead>
                <tbody></tbody>
              </table>
            </div>
          </details>
        </section>
      </div>
    </div>
